export const SAVE='arena-heir-season-one',META='arena-heir-unlocks';
export const CLASSES={dwarf:{name:'Borin',title:'Dwarf',hp:125,melee:18,ranged:7,magic:9,defense:4,speed:170,jump:570,delay:.58,trait:'Heavy hitter · sturdy, slow'},ranger:{name:'Rowan',title:'Ranger',hp:95,melee:10,ranged:16,magic:9,defense:1,speed:245,jump:650,delay:.36,trait:'Swift feet · powerful arrows'},mage:{name:'Aster',title:'Mage',hp:90,melee:9,ranged:10,magic:25,defense:0,speed:205,jump:610,delay:.48,trait:'Arcane power · fragile defenses'},thorn:{name:'Thornkeeper',title:'Forest Master',hp:110,melee:15,ranged:9,magic:16,defense:2,speed:195,jump:610,delay:.5,trait:'Root shock · magic slows foes'}};
export const SLOTS=['melee','ranged','defense','magic','boots'];
const names={dwarf:{melee:['Worn axe','Ironbark axe','Ironheart','Cinder edge','Emberfang'],ranged:['Worn throwing axe','Throwing hatchet','Steel hurler','Rune hurler','Storm hatchet'],defense:['Work clothes','Trail leather','Chain coat','Mountain plate','King’s plate'],magic:['Spark rune','Stone rune','Ember rune','Thunder rune','Crown rune'],boots:['Old boots','Trail boots','Ironstep boots','Wind boots','Sky boots']},ranger:{melee:['Light bow grip','Reinforced grip','Ironwood grip','Moonsteel grip','Royal bow grip'],ranged:['Twig bow','Hunter’s bow','Emerald bow','Moonbow','Sunpiercer'],defense:['Travel clothes','Leather vest','Leafguard','Moon leather','Royal leafguard'],magic:['Nature spark','Briar charm','Root charm','Moon charm','Wildheart charm'],boots:['Old shoes','Tracker shoes','Fleet shoes','Wind shoes','Sky shoes']},mage:{melee:['Wooden staff','Oak staff','Crystal staff','Astral staff','Archmage staff'],ranged:['Spark wand','Quartz wand','Crystal wand','Astral wand','Starlight wand'],defense:['Plain robe','Woven robe','Rune robe','Astral robe','Archmage robe'],magic:['Little spark','Frost orb','Arcane bolt','Starfire','Astral nova'],boots:['Old slippers','Woven boots','Rune boots','Wind slippers','Sky slippers']}};
export function catalog(hero,slot){const h=hero==='thorn'?'dwarf':hero;return names[h][slot].map((name,tier)=>({name,tier,price:[0,25,60,115,190][tier]}));}
export const emptyGear=()=>Object.fromEntries(SLOTS.map(k=>[k,0]));
export function stats(hero,gear){const c=CLASSES[hero];return {hp:c.hp,melee:c.melee+gear.melee*6,ranged:c.ranged+gear.ranged*5,magic:c.magic+gear.magic*7,defense:c.defense+gear.defense*3,speed:c.speed+gear.boots*19-gear.defense*4,jump:c.jump+gear.boots*24,delay:c.delay+gear.melee*.018};}
export function newRun(hero,meta={thorn:false}){if(!Object.hasOwn(CLASSES,hero)||(hero==='thorn'&&!meta.thorn))throw Error('Hero is locked');return {v:1,hero,gold:0,wins:0,gear:emptyGear(),roll:0,finished:false,offers:[]};}
export function reroll(run){run.roll++;const seed=run.roll+run.wins*7;run.offers=[0,1].map(i=>{const hero=['dwarf','ranger','mage'][(seed+i)%3],gear=emptyGear(),tier=Math.min(3,Math.floor(run.wins/2));gear[i?'melee':'defense']=tier;gear[i?'magic':'ranged']=Math.min(3,Math.max(0,tier+(i?1:0)));gear.boots=Math.floor(run.wins/3);return {id:`${run.wins}-${run.roll}-${i}`,hero,gear,name:['Flint','Willow','Morrow','Bran','Lark','Vesper'][(seed+i)%6],style:i?'Aggressive':'Patient',level:run.wins+1+i,prize:35+run.wins*12+i*12,arena:(seed+i)%2?'Moonlit ring':'Moss arena'};});return run.offers;}
export function master(){return {id:'thorn-master',hero:'thorn',gear:{melee:2,ranged:1,magic:2,defense:2,boots:1},name:'Thornkeeper',style:'Master',level:7,prize:150,arena:'Moss arena',master:true};}
export function purchase(run,slot,tier){if(!SLOTS.includes(slot)||!Number.isInteger(tier)||tier<1||tier>4||tier<=run.gear[slot])return false;const item=catalog(run.hero,slot)[tier];if(run.gold<item.price)return false;run.gold-=item.price;run.gear[slot]=tier;return true;}
export function loadRun(raw,meta={thorn:false}){try{const r=JSON.parse(raw);if(r.v!==1||!Object.hasOwn(CLASSES,r.hero)||(r.hero==='thorn'&&!meta.thorn)||!Number.isInteger(r.gold)||r.gold<0||r.gold>1e7||!Number.isInteger(r.wins)||r.wins<0||r.wins>5||typeof r.finished!=='boolean'||(r.finished&&r.wins!==5)||!Number.isInteger(r.roll)||r.roll<0||r.roll>1e8||!r.gear||SLOTS.some(k=>!Number.isInteger(r.gear[k])||r.gear[k]<0||r.gear[k]>4))return null;return {...r,offers:[]};}catch{return null;}}
export function serialize(run){return JSON.stringify({...run,offers:[]});}
function actor(hero,gear,x,face){const st=stats(hero,gear);return {hero,gear:{...gear},stats:st,x,y:0,vy:0,face,hp:st.hp,energy:100,walk:0,attack:null,shotCD:0,magicCD:0,hurt:0,guard:false,guardTime:0,guardLock:0,combo:0,comboUntil:0,slow:0,aiCD:.4,windup:null};}
export function fight(run,offer,training=false){return {time:0,p:actor(run.hero,run.gear,220,1),e:actor(offer.hero,offer.gear,700,-1),offer,training,countdown:training?0:2.4,projectiles:[],events:[],outcome:null,settled:false,damageTaken:0,parries:0,lastEvade:-10};}
const power=s=>s.melee+s.ranged+s.magic+s.defense*3+s.hp*.2+s.speed*.04;
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
function hurt(f,target,source,damage,magic=false,arrival=null){if(target.hp<=0||target.hurt>0)return;if(target.guard&&(arrival===null?source.x*target.face>target.x*target.face:arrival*target.face<0)){if(target.guardTime<.2){target.energy=Math.min(100,target.energy+10);source.windup=null;source.aiCD=.9;f.parries++;f.events.push({type:'parry',x:target.x});return;}damage*=.3;}damage=Math.max(1,Math.round(damage-target.stats.defense*(magic?.4:1)));target.hp=Math.max(0,target.hp-damage);target.hurt=.24;if(target===f.p)f.damageTaken+=damage;f.events.push({type:'hit',x:target.x,y:target.y,damage,enemy:target===f.e});return true;}
function projectile(f,a,kind){f.projectiles.push({owner:a===f.p?'p':'e',x:a.x+a.face*35,y:a.y+65,v:a.face*(kind==='magic'?350:440),damage:kind==='magic'?a.stats.magic:a.stats.ranged,kind,life:2.7});f.events.push({type:'shoot',x:a.x,kind});}
function actions(f,a,input,dt){a.shotCD=Math.max(0,a.shotCD-dt);a.magicCD=Math.max(0,a.magicCD-dt);a.hurt=Math.max(0,a.hurt-dt);a.guardLock=Math.max(0,a.guardLock-dt);a.slow=Math.max(0,a.slow-dt);const move=(input.right?1:0)-(input.left?1:0);if(move&&!a.attack)a.face=move;
 const guarding=!!input.guard&&!a.attack&&a.y===0&&a.energy>4&&a.guardLock===0;a.guardTime=guarding?(a.guard?a.guardTime+dt:0):0;a.guard=guarding;a.energy=clamp(a.energy+(guarding?-25:13)*dt,0,100);if(guarding&&a.energy<5)a.guardLock=1.2;
 if(input.jump&&a.y===0&&!a.guard){a.vy=a.stats.jump;a.y=.1;}
 if(!a.guard&&!a.attack){if(input.magic&&a.magicCD===0&&a.energy>=35){a.energy-=35;a.magicCD=2.8;projectile(f,a,'magic');}else if(input.ranged&&a.shotCD===0){a.shotCD=a.hero==='ranger'?.62:.95;projectile(f,a,'ranged');}else if(input.attack){a.combo=f.time<a.comboUntil?a.combo%3+1:1;a.comboUntil=f.time+1.2;a.attack={t:0,duration:a.stats.delay,strike:a.stats.delay*.43,hit:false,combo:a.combo};}}
 a.x=clamp(a.x+move*a.stats.speed*(a.guard?.2:a.attack?.25:1)*(a.slow?.55:1)*dt,70,850);a.moving=!!move;if(move)a.walk+=dt*11;if(a.y>0){a.vy-=1700*dt;a.y=Math.max(0,a.y+a.vy*dt);if(a.y===0)a.vy=0;}
 if(a.attack){const atk=a.attack;atk.t+=dt;if(!atk.hit&&atk.t>=atk.strike){atk.hit=true;const other=a===f.p?f.e:f.p,d=other.x-a.x;if(Math.abs(d)<120+(atk.combo===3?20:0)&&d*a.face>-20&&Math.abs(other.y-a.y)<85){hurt(f,other,a,a.stats.melee*(atk.combo===3?1.5:1)*(a.y>15?1.2:1));if(atk.combo===3){other.windup=null;other.aiCD=.55;}}f.events.push({type:'slash',x:a.x,face:a.face});}if(atk.t>=atk.duration)a.attack=null;}}
export function tick(f,input,dt){f.events=[];if(f.outcome)return;dt=clamp(dt,0,1/30);f.time+=dt;if(f.countdown>0){f.countdown=Math.max(0,f.countdown-dt);return;}actions(f,f.p,input,dt);const e=f.e,p=f.p,d=p.x-e.x,dist=Math.abs(d);e.face=d<0?-1:1;
 if(!f.training){e.aiCD-=dt;if(e.windup){e.windup.t-=dt;if(e.windup.t<=0){const kind=e.windup.kind;e.windup=null;if(kind==='attack')actions(f,e,{attack:true},0);else projectile(f,e,kind);e.aiCD=.85;}}else if(e.aiCD<=0&&!e.attack){if(dist<130){e.windup={kind:'attack',t:.7};}else if(dist<600){const kind=e.stats.magic>e.stats.ranged&&Math.floor(f.time)%3!==0?'magic':'ranged';e.windup={kind,t:1.05};}}
 const preferred=e.hero==='dwarf'?95:260,canMove=!e.windup&&!e.attack;actions(f,e,{left:canMove&&(d<-preferred||(dist<150&&e.hero!=='dwarf'&&d>0)),right:canMove&&(d>preferred||(dist<150&&e.hero!=='dwarf'&&d<0)),guard:e.aiCD>.55&&dist<130&&f.offer.style==='Patient'},dt);
 }else actions(f,e,{},dt);
 for(const b of f.projectiles){const old=b.x;b.x+=b.v*dt;b.life-=dt;const target=b.owner==='p'?e:p,source=b.owner==='p'?p:e;if(Math.min(old,b.x)-25<=target.x&&Math.max(old,b.x)+25>=target.x){if(b.y>target.y+10&&b.y<target.y+115){const landed=hurt(f,target,source,b.damage,b.kind==='magic',b.v);if(landed&&b.kind==='magic'&&source.hero==='thorn')target.slow=1.5;b.life=0;}else if(target===p&&p.y>30&&b.life>0){f.lastEvade=f.time;b.life=0;f.events.push({type:'evade',x:p.x});}}}
 f.projectiles=f.projectiles.filter(b=>b.life>0&&b.x>-100&&b.x<1020);
 if(f.training){if(e.hp<=0)e.hp=e.stats.hp;return;}
 if(e.hp<=0||p.hp<=0){f.outcome=e.hp<=0?'win':'loss';f.badge=f.outcome==='win'?(f.damageTaken===0?'Untouchable!':f.time-f.lastEvade<1.5?'Perfect Dodge!':power(e.stats)>power(p.stats)*1.1?'Giant Slayer!':'Victory!'):'Try again!';}}
export function settle(run,f,meta){if(f.training||!f.outcome||f.settled||(f.offer.master&&run.wins!==5))return false;f.settled=true;if(f.outcome==='win'){run.gold+=f.offer.prize;if(f.offer.master){run.finished=true;meta.thorn=true;}else run.wins=Math.min(5,run.wins+1);run.offers=[];}return true;}
